@media not (prefers-reduced-motion) {
  .components-animate__appear {
    animation: components-animate__appear-animation 0.1s cubic-bezier(0, 0, 0.2, 1) 0s;
    animation-fill-mode: forwards;
  }
}
.components-animate__appear.is-from-top, .components-animate__appear.is-from-top.is-from-left {
  transform-origin: top left;
}
.components-animate__appear.is-from-top.is-from-right {
  transform-origin: top right;
}
.components-animate__appear.is-from-bottom, .components-animate__appear.is-from-bottom.is-from-left {
  transform-origin: bottom left;
}
.components-animate__appear.is-from-bottom.is-from-right {
  transform-origin: bottom right;
}

@keyframes components-animate__appear-animation {
  from {
    transform: translateY(-2em) scaleY(0) scaleX(0);
  }
  to {
    transform: translateY(0%) scaleY(1) scaleX(1);
  }
}
@media not (prefers-reduced-motion) {
  .components-animate__slide-in {
    animation: components-animate__slide-in-animation 0.1s cubic-bezier(0, 0, 0.2, 1);
    animation-fill-mode: forwards;
  }
  .components-animate__slide-in.is-from-left {
    transform: translateX(100%);
  }
  .components-animate__slide-in.is-from-right {
    transform: translateX(-100%);
  }
}

@keyframes components-animate__slide-in-animation {
  100% {
    transform: translateX(0%);
  }
}
@media not (prefers-reduced-motion) {
  .components-animate__loading {
    animation: components-animate__loading 1.6s ease-in-out infinite;
  }
}

@keyframes components-animate__loading {
  0% {
    opacity: 0.5;
  }
  50% {
    opacity: 1;
  }
  100% {
    opacity: 0.5;
  }
}
.components-autocomplete__popover .components-popover__content {
  padding: 8px;
  min-width: 200px;
}

.components-autocomplete__result.components-button {
  display: flex;
  height: auto;
  min-height: 36px;
  text-align: left;
  width: 100%;
}
.components-autocomplete__result.components-button:focus:not(:disabled) {
  box-shadow: inset 0 0 0 1px #fff, 0 0 0 var(--wp-admin-border-width-focus) var(--wp-admin-theme-color);
  outline: 2px solid transparent;
}

.components-badge {
  box-sizing: border-box;
}
.components-badge *,
.components-badge *::before,
.components-badge *::after {
  box-sizing: inherit;
}
.components-badge {
  background-color: color-mix(in srgb, #fff 90%, var(--base-color));
  color: color-mix(in srgb, #000 50%, var(--base-color));
  padding: 2px 8px;
  min-height: 24px;
  border-radius: 2px;
  line-height: 0;
  max-width: 100%;
  display: inline-block;
}
.components-badge:where(.is-default) {
  background-color: #f0f0f0;
  color: #2f2f2f;
}
.components-badge.has-icon {
  padding-inline-start: 4px;
}
.components-badge.is-info {
  --base-color: #3858e9;
}
.components-badge.is-warning {
  --base-color: #f0b849;
}
.components-badge.is-error {
  --base-color: #cc1818;
}
.components-badge.is-success {
  --base-color: #4ab866;
}

.components-badge__flex-wrapper {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  max-width: 100%;
  font-size: 12px;
  font-weight: 400;
  line-height: 20px;
}

.components-badge__icon {
  flex-shrink: 0;
}

.components-badge__content {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.components-button-group {
  display: inline-block;
}
.components-button-group .components-button {
  border-radius: 0;
  display: inline-flex;
  color: #1e1e1e;
  box-shadow: inset 0 0 0 1px #1e1e1e;
}
.components-button-group .components-button + .components-button {
  margin-left: -1px;
}
.components-button-group .components-button:first-child {
  border-radius: 2px 0 0 2px;
}
.components-button-group .components-button:last-child {
  border-radius: 0 2px 2px 0;
}
.components-button-group .components-button:focus, .components-button-group .components-button.is-primary {
  position: relative;
  z-index: 1;
}
.components-button-group .components-button.is-primary {
  box-shadow: inset 0 0 0 1px #1e1e1e;
}

/**
 * For easier testing of potential regressions, you can use a Button variant matrix
 * available in a special Storybook instance by running `npm run storybook:e2e:dev`.
 *
 * @see https://github.com/WordPress/gutenberg/blob/trunk/test/storybook-playwright/README.md
 */
.components-button {
  display: inline-flex;
  text-decoration: none;
  font-family: inherit;
  font-size: 13px;
  font-weight: 499;
  margin: 0;
  border: 0;
  cursor: pointer;
  appearance: none;
  background: none;
}
@media not (prefers-reduced-motion) {
  .components-button {
    transition: box-shadow 0.1s linear;
  }
}
.components-button {
  height: 36px;
  align-items: center;
  box-sizing: border-box;
  padding: 4px 12px;
  border-radius: 2px;
  color: var(--wp-components-color-foreground, #1e1e1e);
}
.components-button.is-next-40px-default-size {
  height: 40px;
}
.components-button[aria-expanded=true], .components-button:hover:not(:disabled, [aria-disabled=true]) {
  color: var(--wp-components-color-accent, var(--wp-admin-theme-color, #3858e9));
}
.components-button:focus:not(:active) {
  box-shadow: 0 0 0 var(--wp-admin-border-width-focus) var(--wp-components-color-accent, var(--wp-admin-theme-color, #3858e9));
}
