/*-------------Fonts---------------------------------------*/
/*-------------General Style---------------------------------------*/
html {
	overflow-x: hidden !important;
	overflow-y:scroll;
}
body {
	margin: 0;
	padding: 0;
	font-weight: 400;
	font-size: 13px;
	height:100%;
	text-align: center;
	background:#313131;
	color: #000;
	font-family: 'Mukta Vaani', sans-serif;
}
@-o-viewport {
	width: device-width;
}
@-ms-viewport {
	width: device-width;
}
@viewport {
	width: device-width;
}
/* ---------Page preload--------------------------------------*/
.loader {
	position:fixed;
	top:0;
	left:0;
	right:0;
	bottom:0;
	z-index:3;
	-webkit-transform: translate3d(0,0,0);
}
.loader-anim  , .loader-anim2{
	position:absolute;
	top:0;
	bottom:0;
	left:0;
	right:0;
	z-index:2;
	background:#313131;
}
.loader-anim2 {
	z-index:1
}
.loading-text-container {
	position:absolute;
	top:50%;
	left:50%;
	z-index:4;
	width:150px;
	height:90px;
	margin:-45px 0 0 -75px;
	font-family: 'Oswald', sans-serif;
	font-weight:700;
}
.loading-text {
	font-size:48px;
	color:#fff;
	text-align:left;
	text-transform:uppercase;
	display:block;
	line-height:50px;
	position:relative;
	z-index:2;
}
.loading-text strong {
	display:block;
}
.loader_count {
	position:absolute;
	right:-40px;
	top:-150px;
	font-size:198px;
	z-index:1;
}
.page-load {
	position:fixed;
	top:80px;
	left:80px;
	right:0;
	bottom:0;
	z-index:119;
	-webkit-transform: translate3d(0,0,0);
	display:none;
}
.pl-row {
	float:left;
	width:100%;
	overflow:hidden;
	height:25%;
	position:relative;
	z-index:1;
}
.pl-row  span {
	position: absolute;
	left:0;
	right:100%;
	top:0;
	bottom:0;
}
.pl-row  span.pl-row-anim {
	z-index:2;
	background:#292929;
}
.pl-row  span.pl-row-anim2 {
	z-index:1;
}
.pl-spinner   {
	position:absolute;
	top:50%;
	left:50%;
	z-index:4;
	width:40px;
	height:40px;
	margin:-20px 0 0 -20px;
	border-radius:100%;
	background:#292929;
	box-shadow: 0px 0px 0px 12px rgba(255,255,255,0.05);
  	transition: all 500ms cubic-bezier(.19,1,.22,1) 0ms;
	transform:scale(0);
}
.pl-spinner.act-loader {
	transform:scale(1.0);
}
.pl-spinner:before  {
	content:'';
	position:absolute;
	top:0;
	left:0;
	right:0;
	bottom:0;
	border-radius:100%;
	border:2px solid  rgba(255,255,255,0.2);
	animation: rotate 1s cubic-bezier(0.770, 0.000, 0.175, 1.000) infinite;
	box-sizing:border-box;
}
@keyframes rotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
/* ------Cursor------------------------------------------------------------ */
.element {
	position: fixed;
	left:0;
	top:0;
	width: 30px;
	height: 30px;
	pointer-events: none;
	z-index:10000;
}
.element-item {
	position: fixed;
	transform: translate(-50%, -50%);
	width: 30px;
	height: 30px;
	border-radius: 50%;
	pointer-events: none;
	opacity:1;
	box-sizing:border-box;
	border:1px solid  rgba(255,255,255,0.4);
	transform: scale(1.0);
}
.element-item:before {
	content:'';
	position:absolute;
	top:50%;
	left:50%;
	width:6px;
	height:6px;
	margin:-3px 0 0 -3px;
	background:#fff;
	border-radius:100%;
	z-index:-1;
	transform: scale(1.0);
  	transition: all 1000ms cubic-bezier(.19,1,.22,1) 0ms;
}
.element-item.white_blur  {
	border-color: rgba(51,51,51,0.5);
}
.element-item.elem_hover:before {
	opacity:0.2;
	transform: scale(6.5);
}
.element-item.elem_hover {
	border-color:transparent;
}
.element-item:after {
	font-family: Font Awesome\ 5 Pro;
	content: "";
	position:absolute;
	font-size:7px;
	left:50%;
	color:#fff;
	top:50%;
	width: 14px;
	height: 14px;
	font-weight:100;
	line-height:14px;
	margin:-7px 0 0 -7px;
	opacity:0;
  	transition: all 1000ms cubic-bezier(.19,1,.22,1) 0ms;
	transform: scale(0);
}
.element-item.slider_hover:before , .element-item.close-icon:before {
	transform: scale(8.8);
}
.element-item.slider_hover {
	border-color:transparent;
	width: 60px;
	height: 60px;
}
.element-item.slider_hover:after {
	transform: scale(1.0);
	opacity:1;
	content: "Swipe";
	font-family: 'Mukta Vaani', sans-serif;
	text-transform:uppercase;
	font-size:10px !important;
	letter-spacing:2px;
	text-indent:-10px
}
.element-item.slider_linknext:after {
	content: "Next";
	text-indent:-8px
}
.element-item.close-icon:after {
	transform: scale(1.5);
	opacity:1;
	content: "\f00d";
	color:#fff;
	line-height:16px;
}
/*--------------Typography--------------------------------------*/
p {
	font-size: 12px;
	line-height: 24px;
	padding-bottom: 10px;
	font-weight: 500;
    color: #5e646a;
    font-family: 'Roboto', sans-serif;
}
blockquote {
	float: left;
	padding: 10px 20px;
	margin: 0 0 20px;
	font-size: 17.5px;
	border-left: 15px solid #eee;
	position: relative;
}
blockquote:before {
	font-family: Font Awesome\ 5 Pro;
	content: "\f10e";
	position: absolute;
	color: #ccc;
	bottom: 3px;
	font-size: 43px;
	right: 6px;
	opacity: 0.4
}
blockquote p {
	font-family: Georgia, "Times New Roman", Times, serif;
	font-style: italic;
	color: #666;
}
.bold-title {
	margin: 15px 0;
	font-size: 24px;
	text-align: left;
	font-weight: 600;
}
/*--------------General--------------------------------------*/
#main {
	height: 100%;
	width: 100%;
	position: absolute;
	top: 0;
	left: 0;
	z-index: 2;
	opacity: 1;
}
.fl-wrap {
	float: left;
	width: 100%;
	position: relative;
}
.full-height {
	height:100%;
}
.hidden-item , .hov_zoom{
	overflow:hidden;
}
.content {
	float: left;
	width: 100%;
	position: relative;
	z-index: 5;
}
.container {
	max-width: 1224px;
	width: 92%;
	margin: 0 auto;
	position: relative;
	z-index: 5;
}
.small-container {
	max-width:800px;
}
#wrapper {
	position: absolute;
	top: 80px;
	left: 80px;
	right: 80px;
	bottom: 0;
	z-index: 3;
}
.respimg , .single-slider img {
	width: 100%;
	height: auto;
}
.bg {
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	z-index: 1;
	background-size: cover;
	background-attachment: scroll;
	background-position: center;
	background-repeat: repeat;
	background-origin: content-box;
}
.overlay {
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	background: #000;
	opacity: 0.4;
	z-index: 3;
}
/* ------header------------------------------------------------------------ */
.main-header {
	position:fixed;
	top:0;
	left:0;
	width:70%;
	z-index:20;
	height:80px;
	background:#313131;
	-webkit-transform: translate3d(0,0,0)
}
.logo-holder {
	position:absolute;
	top:20px;
	left:26px;
}
.logo-holder img {
	width:auto;
	height:34px;
}
.header-contacts {
	float:right;
	position:relative;
	height:80px;
	line-height:80px;
	right:100px;
}
.contacts-btn {
	display:none;
}
.header-contacts:after {
	content:'';
